INSERT INTO public.reading_sets (
    set_id, title, title_zh, grade, grade_band, content_origin, difficulty, topic, passage,
    word_count, estimated_minutes, sort_order, version, updated_at
) VALUES (
    'r09a-03',
    $seedie$A City Without Plastic Bags$seedie$,
    $seedie$没有塑料袋的城市$seedie$,
    9,
    'g9a',
    'ai_generated',
    $seedie$medium$seedie$,
    $seedie$environment$seedie$,
    $seedie$Last year our city encouraged shops to stop giving free plastic bags. At first, people complained. They forgot cloth bags and held milk bottles awkwardly in their hands.

After three months, habits shifted. Markets sold cheap foldable bags near the entrance. Students designed posters showing how plastic breaks into tiny pieces that harm fish. Some cafés offered a small discount to customers who brought cups.

Change rarely feels comfortable on day one. Yet when rules, design, and education work together, daily life can become cleaner. I still forget my bag sometimes—but now I turn back for it, because the new normal expects me to.$seedie$,
    104,
    9,
    502,
    1,
    2026080701
)
