INSERT INTO public.reading_sets (
    set_id, title, title_zh, grade, grade_band, content_origin, difficulty, topic, passage,
    word_count, estimated_minutes, sort_order, version, updated_at
) VALUES (
    'r09a-04',
    $seedie$The Science Behind a Fever$seedie$,
    $seedie$发烧背后的科学$seedie$,
    9,
    'g9a',
    'ai_generated',
    $seedie$medium$seedie$,
    $seedie$health_science$seedie$,
    $seedie$When you catch a cold, your body temperature may rise. A fever is not the enemy itself; it is often a sign that the immune system is fighting invaders. Higher temperature can make it harder for some germs to grow.

However, a very high fever needs care. Doctors advise rest, enough water, and medicine when necessary. Cold baths that shock the body are not always helpful. Watching for warning signs—such as unusual sleepiness or lasting pain—matters more than guessing alone.

Understanding fever helps us respond calmly. Panic wastes energy that the body needs for recovery. Science turns a scary feeling into a signal we can manage with good habits and timely help.$seedie$,
    112,
    9,
    503,
    1,
    2026080701
)
