INSERT INTO public.reading_sets (
    set_id, title, title_zh, grade, grade_band, content_origin, difficulty, topic, passage,
    word_count, estimated_minutes, sort_order, version, updated_at
) VALUES (
    'r09a-05',
    $seedie$Remembering My Grandfather's Workshop$seedie$,
    $seedie$祖父的修理铺$seedie$,
    9,
    'g9a',
    'ai_generated',
    $seedie$medium$seedie$,
    $seedie$values_narrative$seedie$,
    $seedie$My grandfather repaired bicycles in a small workshop behind our old house. The air smelled of oil and metal. Neighbours came with broken chains and flat tires, and he always found a way.

He taught me to name tools before using them. "Respect the work," he said, "and the work will respect your hands." When I rushed, screws fell; when I slowed down, problems became puzzles.

He passed away last winter, but I still keep his small wrench. Whenever a project at school feels messy, I remember his patience. Skill is not only talent. It is attention repeated until care becomes natural.$seedie$,
    102,
    9,
    504,
    1,
    2026080701
)
