INSERT INTO public.reading_sets (
    set_id, title, title_zh, grade, grade_band, content_origin, difficulty, topic, passage,
    word_count, estimated_minutes, sort_order, version, updated_at
) VALUES (
    'r09b-01',
    $seedie$Preparing for the Senior High Entrance Mindset$seedie$,
    $seedie$中考心态准备$seedie$,
    9,
    'g9b',
    'ai_generated',
    $seedie$hard$seedie$,
    $seedie$exam_life$seedie$,
    $seedie$As the senior high entrance exam approaches, many students focus only on more papers. Equal attention should go to mindset. Sleep, short breaks, and honest talks with teachers reduce the fog of anxiety.

Comparing scores with classmates every hour rarely helps. A better question is: which weak skill improved this week? Small progress charts turn fear into information. Parents can support by listening first, not only by adding tasks.

Exam days test knowledge, but the months before test habits. Calm is not empty; it is trained. A clear desk, a realistic timetable, and kindness toward yourself are part of preparation too.$seedie$,
    101,
    9,
    600,
    1,
    2026080701
)
