INSERT INTO public.reading_sets (
    set_id, title, title_zh, grade, grade_band, content_origin, difficulty, topic, passage,
    word_count, estimated_minutes, sort_order, version, updated_at
) VALUES (
    'r09b-02',
    $seedie$How Online Rumours Travel$seedie$,
    $seedie$网络谣言如何传播$seedie$,
    9,
    'g9b',
    'ai_generated',
    $seedie$hard$seedie$,
    $seedie$media_literacy$seedie$,
    $seedie$A rumour can travel faster than a fact because emotion moves quickly. Shocking headlines invite clicks, and friends forward messages before checking sources. By the time a correction appears, many people have already formed an opinion.

Media literacy asks simple questions: Who published this? What evidence is shown? Can another reliable source confirm it? Screenshots without dates or links deserve extra doubt.

Schools now teach students to pause before sharing. Silence is not weakness when information is unclear; it is responsibility. In a networked world, each forward is a choice that shapes what others believe.$seedie$,
    95,
    9,
    601,
    1,
    2026080701
)
