INSERT INTO public.reading_sets (
    set_id, title, title_zh, grade, grade_band, content_origin, difficulty, topic, passage,
    word_count, estimated_minutes, sort_order, version, updated_at
) VALUES (
    'r09b-03',
    $seedie$The Return of Second-Hand Book Markets$seedie$,
    $seedie$旧书市的回归$seedie$,
    9,
    'g9b',
    'ai_generated',
    $seedie$medium$seedie$,
    $seedie$public_life$seedie$,
    $seedie$On weekends, a second-hand book market opens near the old train station. Tables hold novels, textbooks, and comics with soft corners. Prices are low, and conversations are long.

Buyers look for knowledge and for stories behind the pages—notes in margins, tickets used as bookmarks. Sellers clear shelves at home and keep books circulating instead of becoming waste.

I bought a geography atlas for five yuan. Someone had underlined rivers in blue ink. Their study path briefly met mine. In a digital age, paper still connects strangers through shared curiosity.$seedie$,
    89,
    9,
    602,
    1,
    2026080701
)
