INSERT INTO public.reading_sets (
    set_id, title, title_zh, grade, grade_band, content_origin, difficulty, topic, passage,
    word_count, estimated_minutes, sort_order, version, updated_at
) VALUES (
    'r09b-04',
    $seedie$Teamwork in a Robot Contest$seedie$,
    $seedie$机器人比赛中的团队协作$seedie$,
    9,
    'g9b',
    'ai_generated',
    $seedie$hard$seedie$,
    $seedie$stem$seedie$,
    $seedie$Our school robot team entered a city contest. Building the machine was hard, but sharing roles was harder. One member wanted to code alone; another insisted on redesigning the arms every night.

We held a short meeting and wrote a task board: sensors, code, testing, and documentation. Arguments became decisions with deadlines. When a wheel failed on stage, the tester already had a spare because the checklist required it.

We did not win first prize, but judges praised our clear logbook. Innovation needs talent; finishing needs teamwork. The robot moved, and so did our way of working together.$seedie$,
    98,
