INSERT INTO public.reading_sets (
    set_id, title, title_zh, grade, grade_band, content_origin, difficulty, topic, passage,
    word_count, estimated_minutes, sort_order, version, updated_at
) VALUES (
    'r09b-05',
    $seedie$A Thank-You Speech I Almost Skipped$seedie$,
    $seedie$差点跳过的感谢词$seedie$,
    9,
    'g9b',
    'ai_generated',
    $seedie$medium$seedie$,
    $seedie$growth$seedie$,
    $seedie$At the end-of-term ceremony, I was asked to thank our volunteers in one minute. I nearly refused because public speaking still scares me. My teacher said courage grows in small rooms before big halls.

I wrote three lines: who helped, what they did, and why it mattered. I practiced twice in an empty classroom. On stage my voice shook, yet I finished. Applause was short, but relief was long.

Avoiding fear keeps it large; facing it with a plan makes it manageable. The speech was not perfect. It was honest—and that was enough for a Grade 9 afternoon.$seedie$,
    98,
    9,
    604,
    1,
    2026080701
)
